candidates.raw:
double field_norm;
double b2;
adcs_vec3_t field_unit;
adcs_vec3_t h_total, h_par, h_perp;
double par_scalar;
double dump_mag;
size_t i;
int invalid = 0;
adcs_vec3_t zero_v = {0.0, 0.0, 0.0};
adcs_actuator_command_t cmd;
adcs_vec3_t torque;
adcs_status_t st;

/* 1. basic input validation */
if ((wd_input.enable != 0) && (wd_input.enable != 1)) invalid = 1;
if (wd_input.wheels == NULL) invalid = 1;
if (wd_input.wheel_count != 4U) invalid = 1;
if (wd_input.field_body_t == NULL) invalid = 1;
if ((!invalid) && (!adcs_is_finite_vec3(wd_input.field_body_t))) invalid = 1;
field_norm = 0.0;
if (!invalid) field_norm = adcs_vec3_norm(wd_input.field_body_t);
if ((!invalid) && (!(field_norm > ADCS_EPS_NORM))) invalid = 1;

/* 2. config validation */
if ((!invalid) &&
    ((!isfinite(wd_config.start_nms)) || (!isfinite(wd_config.stop_nms)) ||
     (!isfinite(wd_config.gain_s_inv)) || (!isfinite(wd_config.max_dipole_a_m2)) ||
     (!isfinite(wd_config.max_wheel_speed_rad_s)) ||
     (!(wd_config.stop_nms >= 0.0)) || (!(wd_config.stop_nms < wd_config.start_nms)) ||
     (!(wd_config.gain_s_inv >= 0.0)) || (!(wd_config.max_dipole_a_m2 >= 0.0)) ||
     (!(wd_config.max_wheel_speed_rad_s > 0.0)) ||
     (wd_config.required_high < 1U) || (wd_config.required_high > 100U) ||
     (wd_config.required_low < 1U) || (wd_config.required_low > 100U) ||
     (wd_config.minimum_dump_cycles < 1U) || (wd_config.minimum_dump_cycles > 100U) ||
     (wd_config.cooldown_cycles < 1U) || (wd_config.cooldown_cycles > 100U)))
    invalid = 1;

/* 3. wheel geometry / speed validation */
if (!invalid) {
    for (i = 0U; i < wd_input.wheel_count; i++) {
        adcs_vec3_t axis;
        if ((!isfinite(wd_input.wheels[i].inertia_kg_m2)) ||
            (wd_input.wheels[i].inertia_kg_m2 < 0.0) ||
            (!isfinite(wd_input.wheels[i].speed_rad_s)) ||
            (adcs_vec3_normalize(&wd_input.wheels[i].axis_body, ADCS_EPS_NORM, &axis) !=
             ADCS_OK)) {
            invalid = 1;
            break;
        }
        if (fabs(wd_input.wheels[i].speed_rad_s) > wd_config.max_wheel_speed_rad_s) {
            invalid = 1;
            break;
        }
    }
}

/* 4. compute cluster momentum */
h_total = zero_v;
if (!invalid) {
    st = adcs_wheel_momentum(wd_input.wheels, wd_input.wheel_count, &h_total);
    if (st != ADCS_OK) invalid = 1;
}

/* 5. magnetic decomposition (always recomputed once valid) */
h_par = zero_v;
h_perp = zero_v;
dump_mag = 0.0;
b2 = 0.0;
field_unit = zero_v;
if (!invalid) {
    b2 = adcs_vec3_dot(wd_input.field_body_t, wd_input.field_body_t);
    field_unit = adcs_vec3_scale(wd_input.field_body_t, 1.0 / field_norm);
    par_scalar = adcs_vec3_dot(&h_total, &field_unit);
    h_par = adcs_vec3_scale(&field_unit, par_scalar);
    h_perp = adcs_vec3_sub(&h_total, &h_par);
    dump_mag = adcs_vec3_norm(&h_perp);
}

/* 6. invalid latch: FAULT and zero vector outputs */
if (invalid) {
    wd_state.mode = WD_FAULT;
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    wd_output.mode = WD_FAULT;
    wd_output.momentum_nms = zero_v;
    wd_output.parallel_momentum_nms = zero_v;
    wd_output.dumpable_momentum_nms = zero_v;
    wd_output.dipole_a_m2 = zero_v;
    wd_output.torque_nm = zero_v;
    wd_output.dumpable_magnitude_nms = 0.0;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
    return;
}

/* 7. disable resets all state */
if (wd_input.enable == 0) {
    wd_state.mode = WD_OFF;
    wd_state.high_cycles = 0U;
    wd_state.low_cycles = 0U;
    wd_state.elapsed = 0U;
    wd_output.mode = WD_OFF;
    wd_output.momentum_nms = h_total;
    wd_output.parallel_momentum_nms = h_par;
    wd_output.dumpable_momentum_nms = h_perp;
    wd_output.dumpable_magnitude_nms = dump_mag;
    wd_output.dipole_a_m2 = zero_v;
    wd_output.torque_nm = zero_v;
    wd_output.high_cycles = 0U;
    wd_output.low_cycles = 0U;
    wd_output.elapsed = 0U;
    wd_output.saturation_mask = 0U;
    return;
}

/* 8. state machine transitions */
switch (wd_state.mode) {
case WD_OFF:
case WD_ARMING:
    if (dump_mag >= wd_config.start_nms) {
        wd_state.high_cycles++;
    } else {
        wd_state.high_cycles = 0U;
    }
    if (wd_state.high_cycles >= wd_config.required_high) {
        wd_state.mode = WD_DUMPING;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
    } else {
        wd_state.mode = WD_ARMING;
    }
    break;
case WD_DUMPING:
    wd_state.elapsed++;
    if (wd_state.elapsed >= wd_config.minimum_dump_cycles) {
        if (dump_mag <= wd_config.stop_nms) {
            wd_state.low_cycles++;
        } else {
            wd_state.low_cycles = 0U;
        }
    }
    if (wd_state.low_cycles >= wd_config.required_low) {
        wd_state.mode = WD_COOLDOWN;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
    }
    break;
case WD_COOLDOWN:
    wd_state.elapsed++;
    if (wd_state.elapsed >= wd_config.cooldown_cycles) {
        wd_state.mode = WD_OFF;
        wd_state.high_cycles = 0U;
        wd_state.low_cycles = 0U;
        wd_state.elapsed = 0U;
    }
    break;
case WD_FAULT:
default:
    break;
}

/* 9. publish non-commanding */
wd_output.mode = wd_state.mode;
wd_output.momentum_nms = h_total;
wd_output.parallel_momentum_nms = h_par;
wd_output.dumpable_momentum_nms = h_perp;
wd_output.dumpable_magnitude_nms = dump_mag;
wd_output.high_cycles = wd_state.high_cycles;
wd_output.low_cycles = wd_state.low_cycles;
wd_output.elapsed = wd_state.elapsed;

/* 10. command generation */
if (wd_state.mode == WD_DUMPING) {
    st = adcs_momentum_unload_dipole(&h_total, wd_input.field_body_t,
                                     wd_config.gain_s_inv, wd_config.max_dipole_a_m2,
                                     &cmd, &torque);
    if (st != ADCS_OK) {
        wd_state.mode = WD_FAULT;
        wd_output.mode = WD_FAULT;
        wd_output.dipole_a_m2 = zero_v;
        wd_output.torque_nm = zero_v;
        wd_output.saturation_mask = 0U;
        wd_output.high_cycles = 0U;
        wd_output.low_cycles = 0U;
        wd_output.elapsed = 0U;
        return;
    }
    wd_output.dipole_a_m2 = cmd.command;
    wd_output.torque_nm = torque;
    wd_output.saturation_mask = cmd.saturated_axes;
} else {
    wd_output.dipole_a_m2 = zero_v;
    wd_output.torque_nm = zero_v;
    wd_output.saturation_mask = 0U;
}

